mapper.update:
/* com.portal.user.poll.qqm.QustnrQestnManageMapper.updateQustnrQestnManage */
UPDATE LETTNQUSTNRQESITM
   SET QESTN_SN        = #{qestnSn},
       QESTN_TY_CODE   = #{qestnTyCode},
       QESTN_CN        = #{qestnCn},
       MXMM_CHOISE_CO  = #{mxmmChoiseCo},
       LAST_UPDT_PNTTM = SYSDATE(),
       LAST_UPDUSR_ID  = #{lastUpdusrId}
 WHERE QUSTNR_QESITM_ID = #{qestnrQesitmId}

mapper.select:
/* com.portal.user.poll.qqm.QustnrQestnManageMapper.selectQustnrQestnManageList */ SELECT a.QUSTNR_QESITM_ID AS qestnrQesitmId, a.QESTNR_ID, ( SELECT q.QUSTNR_SJ FROM LETTNQESTNRINFO q WHERE q.QESTNR_ID = a.QESTNR_ID ) AS QESTNR_SJ, a.QESTN_SN, a.QESTN_TY_CODE, a.QESTN_CN, a.MXMM_CHOISE_CO, a.QUSTNR_TMPLAT_ID AS qestnrTmplatId, DATE_FORMAT(a.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, a.FRST_REGISTER_ID, ( SELECT u.USER_NM FROM COMVNUSERMASTER u WHERE u.ESNTL_ID = a.FRST_REGISTER_ID ) AS FRST_REGISTER_NM, DATE_FORMAT(a.LAST_UPDT_PNTTM, '%Y-%m-%d') AS LAST_UPDT_PNTTM, a.LAST_UPDUSR_ID FROM LETTNQUSTNRQESITM a WHERE 1 = 1
AND a.QESTN_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND a.MXMM_CHOISE_CO LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY a.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.poll.qqm.QustnrQestnManageMapper.selectQustnrQestnManageListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQUSTNRQESITM WHERE 1 = 1
AND QESTN_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND MXMM_CHOISE_CO LIKE CONCAT('%', #{searchKeyword}, '%')
